const references = (...ids: string[]): HistorySource[] => ids.map((id) => {
  const found = HISTORY_EARLY_SOURCES.find((entry) => entry.id === id);
  if (!found) throw new Error(`Unknown history source: ${id}`);
  return found;
});
const block = (text: string, evidence: HistoryBlock["evidence"], ...sourceIds: string[]): HistoryBlock => ({ text, evidence, sourceIds });
const choice = (id: string, text: string, correct: boolean, feedback: string): HistoryChoice => ({ id, text, correct, feedback });
const visual = (kind: HistoryVisual["kind"], title: string, nodes: readonly [string, string][], caption: string, sourceIds: string[]): HistoryVisual => ({ kind, title, nodes: nodes.map(([label, detail]) => ({ label, detail })), caption, sourceIds });
const activity = (id: string, title: string, scenario: string, prompt: string, choices: HistoryChoice[], reasonPrompt: string, reasons: HistoryChoice[], sourceIds: string[], takeaway: string, kind: HistoryActivity["kind"] = "choice"): HistoryActivity => ({
  id, kind, title, scenario, fictional: true,
  evaluates: "Choisir une conclusion compatible avec les documents et une justification qui en respecte la portée. Les deux choix sont évalués séparément.",
  steps: [{ id: `${id}-step`, prompt, choices, reasonPrompt, reasons, sourceIds }], takeaway,
});

